class Solution {
    long long paths(const vector<string>& g) {
        int m=g.size(),n=g[0].size();
        vector<vector<long long>> dp(m,vector<long long>(n));
        if(g[0][0]=='.') dp[0][0]=1;
        for(int i=0;i<m;i++)for(int j=0;j<n;j++){
            if(g[i][j]=='#'){dp[i][j]=0;continue;}
            if(i)dp[i][j]+=dp[i-1][j];
            if(j)dp[i][j]+=dp[i][j-1];
        }
        return dp[m-1][n-1];
    }
public:
    vector<string> createGrid(int m,int n,int k) {
        if(m==1||n==1) return k==1?vector<string>(m,string(n,'.')):vector<string>();
        // With two rows or columns, use the full short strip as a gadget.
        int a=min(m,3), b=min(n,3);
        if(m==2) b=min(n,5);
        if(n==2) a=min(m,5);
        int cells=a*b;
        for(int mask=0;mask<(1<<cells);mask++) {
            vector<string> g(m,string(n,'#'));
            for(int i=0;i<a;i++)for(int j=0;j<b;j++)
                if(!(mask&(1<<(i*b+j))))g[i][j]='.';
            // Extend from the gadget's exit (a-1,b-1) along a single corridor.
            for(int j=b;j<n;j++)g[a-1][j]='.';
            for(int i=a;i<m;i++)g[i][n-1]='.';
            if(paths(g)==k)return g;
        }
        return {};
    }
};
